import sys
import csv
import re
from datetime import datetime

def parse_date(date_str):
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return None

def validate_row(line_number, row):
    if len(row) != 4:
        return False
    date_str, category, amount_str, note = row
    if not parse_date(date_str):
        return False
    try:
        float(amount_str)
    except ValueError:
        return False
    return True

def process_csv(input_file):
    state = {}
    expenses = []
    month_pattern = re.compile(r'^\d{4}-\d{2}')

    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader)
        line_number = 1
        for row in reader:
            if not validate_row(line_number, row):
                print(f"line {line_number}: invalid row", file=sys.stderr)
                line_number += 1
                continue
            date_str, category, amount_str, note = row
            month_key = date_str[:7]
            if month_pattern.match(month_key):
                try:
                    amount = float(amount_str)
                except ValueError:
                    print(f"line {line_number}: invalid row", file=sys.stderr)
                    line_number += 1
                    continue
                expenses.append((date_str, category, amount, note))
                state[month_key] = state.get(month_key, 0.0) + amount
            line_number += 1

    return state, expenses

def write_state(state):
    sorted_months = sorted(state.items())
    with open('expense_state.txt', 'w') as f:
        for month, total in sorted_months:
            f.write(f"{month}\t{total:.2f}\n")

def generate_html(state, expenses):
    with open('report.html', 'w') as f:
        f.write('''<!DOCTYPE html>
<html><head><title>Expense Report</title></head><body>
<h1>Expense Report</h1>
<h2>Monthly Totals</h2>
<table>
''')
        for month, total in state.items():
            f.write(f'<tr><th>{month}</th><th>{total:.2f}</th></tr>\n')
        f.write('''</table>
<h2>Expenses</h2>
<table>
''')
        for date, category, amount, note in expenses:
            f.write(f'<tr><th>{date}</th><th>{category}</th><th>{amount:.2f}</th><th>{note}</th></tr>\n')
        f.write('''</table>
</body></html>''')

def main():
    if len(sys.argv) != 3:
        print("Usage: python expense_report.py expenses.csv report.html", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    output_html = sys.argv[2]

    state, expenses = process_csv(input_file)
    write_state(state)
    generate_html(state, expenses)

if __name__ == "__main__":
    main()
